func TestLoadEnv(t *testing.T) {
	ctx := t.Context()
	p := testkit.NewInMemorySecretsProvider()
	for name, v := range map[string]string{"cfg/db-password": "pw", "cfg/api.key": "k", "cfg/keep": "new", "cfg/bin": "\xff"} {
		if _, err := p.Set(ctx, name, v, nil); err != nil {
			t.Fatal(err)
		}
	}
	const prefix = "GROW_LOADENV_TEST_"
	t.Setenv(prefix+"KEEP", "existing")
	for _, n := range []string{"DB_PASSWORD", "API_KEY", "BIN", "MAPPED"} {
		t.Setenv(prefix+n, "")
		_ = os.Unsetenv(prefix + n)
	}
	_ = p.Delete(ctx, "cfg/bin", nil)
	set, err := p.LoadEnv(ctx, "cfg", &__PKG__.LoadEnvOptions{Prefix: prefix})
	if err != nil {
		t.Fatal(err)
	}
	if len(set) != 2 || set[prefix+"DB_PASSWORD"] != "cfg/db-password" || os.Getenv(prefix+"API_KEY") != "k" || os.Getenv(prefix+"KEEP") != "existing" {
		t.Fatalf("set %v", set)
	}
	set, err = p.LoadEnv(ctx, "cfg", &__PKG__.LoadEnvOptions{Prefix: prefix, Override: true})
	if err != nil || len(set) != 3 || os.Getenv(prefix+"KEEP") != "new" {
		t.Fatalf("override: %v %v", set, err)
	}
	set, err = p.LoadEnvMapping(ctx, map[string]string{prefix + "MAPPED": "cfg/keep"}, nil)
	if err != nil || len(set) != 1 || os.Getenv(prefix+"MAPPED") != "new" {
		t.Fatalf("mapping: %v %v", set, err)
	}
	if _, err := p.Set(ctx, "cfg/bin", []byte{0xff}, nil); err != nil {
		t.Fatal(err)
	}
	if _, err := p.LoadEnv(ctx, "cfg", &__PKG__.LoadEnvOptions{Prefix: prefix}); !errors.Is(err, __PKG__.ErrValidation) {
		t.Fatalf("binary: %v", err)
	}
	if _, err := p.LoadEnvMapping(ctx, map[string]string{prefix + "BAD=": "cfg/keep"}, &__PKG__.LoadEnvOptions{Override: true}); !errors.Is(err, __PKG__.ErrValidation) {
		t.Fatalf("invalid variable name: %v", err)
	}
	p.SetError(__PKG__.ErrUnavailable)
	if _, err := p.LoadEnvMapping(ctx, map[string]string{prefix + "MAPPED2": "cfg/keep"}, nil); !errors.Is(err, __PKG__.ErrUnavailable) {
		t.Fatalf("mapping error: %v", err)
	}
	if __PKG__.EnvName("P_", "a-b.c/d_9") != "P_A_B_C_D_9" {
		t.Fatal("EnvName")
	}
}
